llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Gemcitabine, a 2'-deoxycytidine analog that is also a cytidine deaminase substrate, has an oral bioavailability of only 10% in humans, supporting low F for the query decitabine, which shares the cytosine nucleoside scaffold and CDA liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Cladribine, a 2-deoxyribose nucleoside with a similar sugar and amino-azine base, has an absolute oral bioavailability of 55% in patients, suggesting that 2-deoxyriboside nucleosides can be well absorbed orally.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "Lamivudine, a cytidine analog with a modified sugar, has an absolute oral bioavailability of 95%, indicating that cytosine nucleoside analogs can achieve high F when not subject to cytidine deaminase metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "2FddC, a 2'-deoxycytidine analog, has an oral bioavailability of about 50%, showing that deoxycytidine analogs can be orally bioavailable if they are resistant to cytidine deaminase.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low because decitabine is a 5-aza-2'-deoxycytidine that is rapidly inactivated by cytidine deaminase; the most mechanistically relevant analogue, gemcitabine, has F ~10%, while high-F cytidine analogues are CDA-resistant or structurally modified.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for decitabine in the evidence set.",
    "Cytidine deaminase-mediated first-pass metabolism is inferred from gemcitabine and known pharmacology rather than directly measured for the query.",
    "High-F cytidine analogues differ in CDA susceptibility, limiting direct transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

